            parts.append(["w", "-", "-", "0", "1"][len(parts) - 1])
        b = [OFF] * 120
        for s in SQUARES:
            b[s] = EMPTY
        self.kings = [0, 0]  # [white, black]
        rows = parts[0].split("/")
